entries[43505] = { ["name"] = "Rezept: Gigantisches Festmahl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein gigantisches Festmahl zubereitet.\nBenötigt Kochkunst von Nordend (50)\n\nGigantisches Festmahl\nBenutzen: Richtet für Eure Gruppe ein großartiges Festmahl her! Stellt im Verlauf von 30 Sek. 6696 Gesundheit und ( 711 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr größer.\nBenötigt Kochkunst von Nordend (1)\nVerkaufspreis:\nBenötigt Tiefseemonsterbauch (2), Mammutlende (2), Steinflossenbarsch (2), Nordische Gewürze" }
entries[43506] = { ["name"] = "Rezept: Kleines Festmahl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein kleines Festmahl zubereitet.\nBenötigt Kochkunst von Nordend (50)\n\nKleines Festmahl\nBenutzen: Richtet für Eure Gruppe ein großartiges Festmahl her! Stellt im Verlauf von 30 Sek. 6696 Gesundheit und ( 711 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr kleiner.\nBenötigt Kochkunst von Nordend (1)\nVerkaufspreis:\nBenötigt Nesselfisch (2), Rhinozerosfleisch (2), Winterlachs (2), Nordische Gewürze" }
