entries[43951] = { ["name"] = "Zügel des Bronzedrachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Bronzedrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Verlorene Zeit kommt niemals zurück. Oh wartet, da ist sie ja. - Chronormu\"\nBeute von:\nEwiger Verderber\nZone:\nDas Ausmerzen von Stratholme" }
entries[43952] = { ["name"] = "Zügel des azurblauen Drachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren azurblauen Drachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Bleibt besser höflich, wenn Ihr mit einem wütenden Drachen sprecht.\"\nBeute von:\nAlexstraszas Geschenk\nOrt:\nAuge der Ewigkeit" }
entries[43953] = { ["name"] = "Zügel des Blaudrachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Blaudrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Stellt Euch nicht zwischen einen Drachen und seinen Zorn.\"\nBeute von:\nAlexstraszas Geschenk\nOrt:\nAuge der Ewigkeit" }
entries[43954] = { ["name"] = "Zügel des Zwielichtdrachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Zwielichtdrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Aber die wichtigste Regel, die Regel, die Ihr niemals vergessen dürft, ist: Egal, wie viel er schreien mag, egal, wie sehr er bettelt, füttert ihn niemals nach Mitternacht.\"\nBeute von:\nSartharion\nOrt:\nDas Obsidiansanktum" }
entries[43955] = { ["name"] = "Zügel des Rotdrachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Rotdrachen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Der Wyrmruhpakt\n- Ehrfürchtig\n\n\"Ihr solltet nicht auf die Fantasien der Barden hören. Ein Drache würde keiner Fliege etwas zuleide tun, solange er nicht zuerst angegriffen wurde.\"\nVerkäufer:\nCielstrasza\nZone:\nDrachenöde\nFraktion:\nDer Wyrmruhpakt - Ehrfürchtig\nKosten:" }
entries[43956] = { ["name"] = "Zügel des schwarzen Kriegsmammuts", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares schwarzes Kriegsmammut oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese meist friedfertigen, intelligenten Tiere gehen eine enge Bindung mit ihren Reitern ein, weshalb sie sich im Kampf als treu und furchtlos erweisen.\"\nVerkäufer:\nRitter Dameron\nZone:\nTausendwinter\nKosten:\n15" }
entries[43958] = { ["name"] = "Zügel des Eismammuts", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares Eismammut oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Söhne Hodirs\n- Respektvoll\nVerkaufspreis:\n\"Viele Eisriesen behaupten, sie hätten den von ihnen bevorzugten weißen Mammuts beigebracht, mit ihrem Trompeten Lawinen auszulösen.\"\nVerkäufer:\nLillehoff\nZone:\nDie Sturmgipfel\nFraktion:\nDie Söhne Hodirs - Respektvoll\nKosten:" }
entries[43959] = { ["name"] = "Zügel des großen schwarzen Kriegsmammuts", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier für 3 Personen beschwört.\nRuft ein großes schwarzes Kriegsmammut herbei! Kann zwei Passagiere aufnehmen, die sich in einer Gruppe mit dem Steuernden befinden müssen.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einst wurden sie von Riesen verwendet, um schwer gepanzerte Krieger zu tragen, doch können diese riesigen Kriegsmammuts auch problemlos einen Reiter kleinerer Statur tragen.\"\nBeute von:\nBossbeute\nOrt:\nArchavons Kammer" }
entries[43961] = { ["name"] = "Zügel des großen Eismammuts", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier für 3 Personen beschwört.\nRuft ein großes Eismammut herbei! Kann zwei Passagiere aufnehmen, die sich in einer Gruppe mit dem Steuernden befinden müssen.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Söhne Hodirs\n- Ehrfürchtig\nVerkaufspreis:\n\"Aufgrund der starken Winde und Lawinen empfehlen die Söhne Hodirs mindestens zwei Begleiter bei Reisen in die gefährlichen Sturmgipfel.\"\nVerkäufer:\nLillehoff\nZone:\nDie Sturmgipfel\nFraktion:\nDie Söhne Hodirs - Ehrfürchtig\nKosten:" }
entries[43962] = { ["name"] = "Zügel des weißen Eisbären", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren weißen Eisbär oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Frostvrykul glauben, dass es ihnen überirdische Macht verleiht, wenn sie eine Halskette mit den Klauen eines Eisbären tragen.\"\nBeute von:\nHyldnirbeute\nOrt:\nDie Sturmgipfel" }
entries[43963] = { ["name"] = "Zügel des braunen Eisbären", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren braunen Eisbären oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten" }
entries[43964] = { ["name"] = "Zügel des schwarzen Eisbären", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schwarzen Eisbären oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Taunka verwenden die Felle schwarzer Eisbären für ihre religiösen Rituale, normalerweise bei Beerdigungen jener, die schwarze Eisbären jagen.\"\nKlassisch" }
