entries[44075] = { ["name"] = "Arkanum der Vorherrschaft", ["text"] = "Wird beim Aufheben gebunden\n\"Eine magische Störung hat dieses Arkanum beschädigt und somit unbrauchbar gemacht.\"\nVerkaufspreis:" }
