entries[44077] = { ["name"] = "Zügel des schwarzen Kriegsmammuts", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares schwarzes Kriegsmammut oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese dunkelfelligen Mammuts, standfest und nicht aus der Ruhe zu bringen, werden für ihren Gleichmut in der Schlacht geschätzt.\"\nVerkäufer:\nSteingardist Mutaha\nZone:\nTausendwinter\nKosten:\n15" }
