entries[44083] = { ["name"] = "Zügel des großen schwarzen Kriegsmammuts", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier für 3 Personen beschwört.\nRuft ein großes schwarzes Kriegsmammut herbei! Kann zwei Passagiere aufnehmen, die sich in einer Gruppe mit dem Steuernden befinden müssen.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Äußerst selten wird ein Kriegsmammut geboren, das noch stärker und lenkbarer als seine Geschwister ist. Sie werden als \"Große\" Mammuts bezeichnet und können mehr als einen Reiter an die Front tragen.\"\nBeute von:\nBossbeute\nOrt:\nArchavons Kammer" }
entries[44084] = { ["name"] = "Einsamer Sternenlichtdiamant", ["text"] = "+ 3 Intelligenz und um 10% verringerte Dauer von Stilleeffekten\n\"Passt nur in einen Sockel der Kategorie Meta.\"\nVerkaufspreis:" }
entries[44086] = { ["name"] = "Zügel des großen Eismammuts", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier für 3 Personen beschwört.\nRuft ein großes Eismammut herbei! Kann zwei Passagiere aufnehmen, die sich in einer Gruppe mit dem Steuernden befinden müssen.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Söhne Hodirs\n- Ehrfürchtig\nVerkaufspreis:\n\"Diese Mammuts hausen in den engen, eisigen Pfaden der Sturmgipfel und sind die einzigen Reittiere, denen die Eisriesen große Lasten und mehrere Reiter anvertrauen.\"\nVerkäufer:\nLillehoff\nZone:\nDie Sturmgipfel\nFraktion:\nDie Söhne Hodirs - Ehrfürchtig\nKosten:" }
