entries[44220] = { ["name"] = "Sendung der Orgrims Hammer", ["text"] = "Questgegenstand" }
entries[44221] = { ["name"] = "Geliehene Greifenzügel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Beschwört einen reitbaren geliehenen Greifen oder gibt ihn wieder frei. Kann nur in den Sturmgipfeln, in Eiskrone und im Sholazarbecken beschworen werden. (3 Sek. Abklingzeit)\n80 ( 80)" }
entries[44222] = { ["name"] = "Pfeilpistole", ["text"] = "Questgegenstand\nBenutzen: Feuert einen giftigen Pfeil auf einen Späher von Orgrims Hammer. (40 Meter Reichweite) (5 Sek. Abklingzeit)" }
entries[44223] = { ["name"] = "Zügel des schwarzen Kriegsbären", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schwarzen Kriegsbären oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Anführer der Horde zu besiegen, ist schon eine Belohnung an sich, doch dieses einschüchternde Wesen ist ein ausgezeichnetes Erinnerungsstück.\"\nErfolg:\nFür die Allianz!\nKategorie:\nSpieler gegen Spieler" }
entries[44224] = { ["name"] = "Zügel des schwarzen Kriegsbären", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schwarzen Kriegsbären oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses beachtliche Reittier wurde mit dem Blut von Allianzanführern erkauft, doch Ihr hättet sie auch umsonst getötet.\"\nErfolg:\nFür die Horde!\nKategorie:\nSpieler gegen Spieler" }
entries[44225] = { ["name"] = "Zügel des gepanzerten Braunbären", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren gepanzerten Braunbären oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Schnelligkeit dieses Bärenreittiers wird durch seine schwere Rüstung erhöht, die mit Magie der Kirin Tor verzaubert wurde.\"\nVerkäufer:\nMei Francis\nZone:\nKristallsangwald\nKosten:" }
entries[44226] = { ["name"] = "Zügel des gepanzerten Braunbären", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren gepanzerten Braunbären oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Schrei \"Für die Horde!\" wirkt noch viel imposanter, wenn Ihr vom Rücken eines schwer gepanzerten Bären aus schreit, der mit Höchstgeschwindigkeit auf die Allianzler zu rast.\"\nVerkäufer:\nMei Francis\nZone:\nKristallsangwald\nKosten:" }
entries[44228] = { ["name"] = "Junges Gemüse", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lässt das Ziel um 50% schrumpfen. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[44229] = { ["name"] = "Geliehene Windreiterzügel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Beschwört einen reitbaren geliehenen Windreiter oder gibt ihn wieder frei. Kann nur in den Sturmgipfeln, in Eiskrone und im Sholazarbecken beschworen werden. (3 Sek. Abklingzeit)\n80 ( 80)" }
entries[44230] = { ["name"] = "Zügel des Wollmammuts", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares Wollmammut oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Wollmammuts stammen direkt von den Vorvätern der Mammutrasse ab und werden als wilder und ursprünglicher angesehen als ihre kurzhaarigen Verwandten.\"\nVerkäufer:\nMei Francis\nZone:\nKristallsangwald\nKosten:" }
entries[44231] = { ["name"] = "Zügel des Wollmammuts", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares Wollmammut oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese wilde Mammutrasse wird nicht zum Reiten gezüchtet. Die meisten Wollmammuts werden in der Wildnis gefangen und von ihren Reitern gezähmt, was sie zu leidenschaftlichen und geschickten Reittieren macht.\"\nVerkäufer:\nMei Francis\nZone:\nKristallsangwald\nKosten:" }
entries[44234] = { ["name"] = "Zügel des Tundramammuts des Reisenden", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier für 3 Personen mit Händlern beschwört.\nRuft ein großes Tundramammut des Reisenden herbei, komplett mit zwei Begleitern!\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Reiter und Händler vertrauen beide nur den stärksten und standhaftesten Mammuts, wenn es darum geht, sie sicher über die frostige Tundra zu tragen.\"\nVerkäufer:\nMei Francis\nZone:\nKristallsangwald\nKosten:" }
entries[44235] = { ["name"] = "Zügel des Tundramammuts des Reisenden", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier für 3 Personen mit Händlern beschwört.\nRuft ein großes Tundramammut des Reisenden herbei, komplett mit zwei Begleitern!\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Uralte Manuskripte beschreiben, wie Händler auf diesen kolossalen Tieren über die gefrorene Tundra reisen, weshalb Gelehrte sie für die ersten gezähmten Reittiere halten.\"\nVerkäufer:\nMei Francis\nZone:\nKristallsangwald\nKosten:" }
